      const auto* to_st = amr_dispatcher_core::catalog::FindStation(
          EffectiveCatalog(), ait->second.dropoff_station);
      if (to_st) {
        const double total = std::hypot(to_st->x - sit->second.x, to_st->y - sit->second.y);
