  void EstopCallback(const std_msgs::msg::Bool::SharedPtr msg);
  void BumperCallback(const std_msgs::msg::Bool::SharedPtr msg);
  // B1 心跳分源：source 与 watched_nodes_ 中登记的来源名一致（"chassis_driver" / "path_tracker"），
