     template<typename RosidlMsgT, typename ProtoT>
     class ProtoDualPublisher {
      public:
       ProtoDualPublisher(rclcpp::Node * node, const std::string & rosidl_name,
                          std::size_t qos_depth, bool enabled)
       : rosidl_topic_(rosidl_name), proto_topic_(ProtoTopicName(rosidl_name)), enabled_(enabled) {
         if (!enabled_) return;
         pub_ = node->create_publisher<ProtoT>(proto_topic_, rclcpp::QoS(qos_depth));
       }
       bool enabled() const {return static_cast<bool>(pub_);}
       const std::string & proto_topic() const {return proto_topic_;}
       bool Publish(const RosidlMsgT & msg) {
         if (!pub_) return false;
         ProtoT proto_msg;
         Project(msg, &proto_msg);
         pub_->publish(proto_msg);
         return true;
       }
       void Activate()   { if (pub_) pub_->on_activate(); }
       void Deactivate() { if (pub_) pub_->on_deactivate(); }
      private:
       static void Project(const RosidlMsgT & in, ProtoT * out) { /* if constexpr chain over 7 pairs, else static_assert(false) */ }
       std::string rosidl_topic_, proto_topic_;
       bool enabled_{false};
       typename rclcpp::Publisher<ProtoT>::SharedPtr pub_;
     };
     ```
