1	// 双发发布器：一次调用同时发布 rosidl 与 protobuf 两路话题。
2	//
3	// ============================================================================
4	// 为什么需要这个封装，而不是在每个节点里写两个 publish
5	// ============================================================================
6	// 双发不是「多写一行 publish」那么简单，它有三个每次都必须处理对的细节：
7	//
8	//   1. 话题名派生。既有代码用 ResolveVehicleTopic 做 per-vehicle 派生，
9	//      proto 话题必须走同一套规则，否则多车场景下 __proto 只发全局名，
10	//      订阅方按车拿不到。这里统一交给调用方传「已解析好的 rosidl 话题名」，
11	//      内部只追加后缀，保证派生只做一次。
12	//
13	//   2. lifecycle 发布器的激活态。dispatcher_node 用的是
14	//      rclcpp_lifecycle::LifecyclePublisher，未激活时 publish 是静默空操作。
15	//      rosidl 侧靠 on_activate/on_deactivate 管理，proto 侧若不同步处理，
16	//      就会出现「节点 active 了但 proto 话题没数据」这种只在运行时可见的偏差。
17	//
18	//   3. 总开关。过渡期必须能一键关掉 proto 侧（回滚、压测、排查），
19	//      而不必改代码或重新构建。开关做成构造参数，由节点参数注入。
20	//
21	// ============================================================================
22	// 为什么不做成模板类去包 rclcpp::Publisher
23	// ============================================================================
24	// rclcpp 的 Publisher 有两种类型（普通 / lifecycle），模板参数无法同时覆盖，
25	// 硬做会导致类型擦除或双重封装。这里选择「持有 proto 发布器 + 提供 Publish(rosidl_msg)
26	// 方法」，rosidl 侧仍由节点自己 publish —— 调用点只多一行，却保住了两侧的
27	// 原生类型和生命周期语义，排查时也不需要在抽象层里找对应关系。
28	#ifndef AMR_DISPATCHER_ROS__PROTO_DUAL_PUBLISHER_HPP_
29	#define AMR_DISPATCHER_ROS__PROTO_DUAL_PUBLISHER_HPP_
30	
31	#include <memory>
32	#include <string>
33	
34	#include <rclcpp/rclcpp.hpp>
35	
36	#include "amr_dispatcher_ros/proto_projection.hpp"
37	
38	// 让 create_publisher<ProtoT> 能通过 rclcpp 的消息类型检查。
39	#include "amr_dispatcher_proto/register_all_types.hpp"
40	
41	namespace amr_dispatcher_ros
42	{
43	
44	/// proto 话题名的后缀。
45	///
46	/// 选 `_proto` 而不是 `/proto/` 子命名空间：ROS 话题名里 `/proto/xxx` 会变成
47	/// 另一个层级，按前缀做 ros2 topic list 通配时会与既有话题分散；后缀形式
48	/// 让 `/chassis/link_health` 与 `/chassis/link_health_proto` 在列表里相邻，
49	/// 运维一眼能看出配对关系。
50	inline constexpr const char * kProtoTopicSuffix = "_proto";
51	
52	/// 由 rosidl 话题名派生 proto 话题名。
53	///
54	/// 入参必须已经是**解析后的最终话题名**（即 ResolveVehicleTopic 的输出），
55	/// 这样 per-vehicle 派生只发生一次，不会出现 `/plan/amr_01_proto` 与
56	/// `/plan_proto/amr_01` 两种不一致的结果。
57	inline std::string ProtoTopicName(const std::string & rosidl_topic)
58	{
59	  return rosidl_topic + kProtoTopicSuffix;
60	}
61	
62	/// 双发器：持有 proto 发布器，提供从 rosidl 消息投影并发布的单一入口。
63	///
64	/// 模板参数 ProtoT 必须是已在 register_all_types.hpp 注册过的类型。
65	template<typename RosidlMsgT, typename ProtoT>
66	class ProtoDualPublisher
67	{
68	public:
69	  /// 构造即创建发布器。
70	  ///
71	  /// \param node        宿主节点（用于 create_publisher 与日志）
72	  /// \param rosidl_name 已解析的 rosidl 话题名（proto 名由它派生）
73	  /// \param qos_depth   QoS 深度。两侧必须一致：若 proto 侧深度更小，
74	  ///                    突发时会先丢 proto 帧，一致性检查器会报「proto 缺帧」
75	  ///                    而不是「消息不一致」，掩盖真正的问题。
76	  /// \param enabled     总开关。false 时完全不创建发布器，
77	  ///                    因此也不会在 DDS 里留下一个空话题。
78	  ProtoDualPublisher(
79	    rclcpp::Node * node, const std::string & rosidl_name, std::size_t qos_depth, bool enabled)
80	  : rosidl_topic_(rosidl_name),
81	    proto_topic_(ProtoTopicName(rosidl_name)),
82	    enabled_(enabled)
83	  {
84	    if (!enabled_) {
85	      return;
86	    }
87	    pub_ = node->create_publisher<ProtoT>(proto_topic_, rclcpp::QoS(qos_depth));
88	  }
89	
90	  /// 是否真正启用了 proto 侧。调用方用它决定是否值得构造 proto 消息。
91	  bool enabled() const {return static_cast<bool>(pub_);}
92	
93	  const std::string & proto_topic() const {return proto_topic_;}
94	
95	  /// 从 rosidl 消息投影并发布。未启用时为空操作。
96	  ///
97	  /// 返回是否真的发布了，便于调用方在测试中断言。
98	  bool Publish(const RosidlMsgT & msg)
99	  {
100	    if (!pub_) {
101	      return false;
102	    }
103	    ProtoT proto_msg;
104	    Project(msg, &proto_msg);
105	    pub_->publish(proto_msg);
106	    return true;
107	  }
108	
109	  /// lifecycle 节点专用：与 rosidl 侧的 on_activate 成对调用。
110	  void Activate()
111	  {
112	    if (pub_) {
113	      pub_->on_activate();
114	    }
115	  }
116	
117	  void Deactivate()
118	  {
119	    if (pub_) {
120	      pub_->on_deactivate();
121	    }
122	  }
123	
124	private:
125	  /// 把具体类型的投影函数绑定进来。
126	  ///
127	  /// 用 if constexpr 做类型分发而不是要求 ProtoT 提供静态 Project 方法：
128	  /// protobuf 生成的类不接受注入，而投影函数是自由函数，只能在此做分派。
129	  /// 分支写错会在编译期落到 else 的 static_assert，不会静默走错路径。
130	  static void Project(const RosidlMsgT & in, ProtoT * out)
131	  {
132	    using amr_dispatcher_interfaces::msg::ChassisLinkHealth;
133	    using amr_dispatcher_interfaces::msg::DispatcherState;
134	    using amr_dispatcher_interfaces::msg::MissionEvent;
135	    using amr_dispatcher_interfaces::msg::SafetyState;
136	    using amr_dispatcher_interfaces::msg::TopologyState;
137	    using amr_dispatcher_interfaces::msg::TrackingError;
138	    using amr_dispatcher_interfaces::msg::VehicleLinkState;
139	    using amr_dispatcher::proto::ChassisLinkHealth;
140	    using amr_dispatcher::proto::DispatcherState;
141	    using amr_dispatcher::proto::MissionEvent;
142	    using amr_dispatcher::proto::SafetyState;
143	    using amr_dispatcher::proto::TopologyState;
144	    using amr_dispatcher::proto::TrackingError;
145	    using amr_dispatcher::proto::VehicleLinkState;
146	
147	    if constexpr (std::is_same_v<RosidlMsgT, ChassisLinkHealth> &&
148	      std::is_same_v<ProtoT, amr_dispatcher::proto::ChassisLinkHealth>)
149	    {
150	      proto_projection::ProjectChassisLinkHealth(in, out);
151	    } else if constexpr (std::is_same_v<RosidlMsgT, TrackingError> &&
152	      std::is_same_v<ProtoT, amr_dispatcher::proto::TrackingError>)
153	    {
154	      proto_projection::ProjectTrackingError(in, out);
155	    } else if constexpr (std::is_same_v<RosidlMsgT, DispatcherState> &&
156	      std::is_same_v<ProtoT, amr_dispatcher::proto::DispatcherState>)
157	    {
158	      proto_projection::ProjectDispatcherState(in, out);
159	    } else if constexpr (std::is_same_v<RosidlMsgT, SafetyState> &&
160	      std::is_same_v<ProtoT, amr_dispatcher::proto::SafetyState>)
161	    {
162	      proto_projection::ProjectSafetyState(in, out);
163	    } else if constexpr (std::is_same_v<RosidlMsgT, TopologyState> &&
164	      std::is_same_v<ProtoT, amr_dispatcher::proto::TopologyState>)
165	    {
166	      proto_projection::ProjectTopologyState(in, out);
167	    } else if constexpr (std::is_same_v<RosidlMsgT, MissionEvent> &&
168	      std::is_same_v<ProtoT, amr_dispatcher::proto::MissionEvent>)
169	    {
170	      proto_projection::ProjectMissionEvent(in, out);
171	    } else {
172	      static_assert(
173	        !std::is_same_v<RosidlMsgT, RosidlMsgT>,
174	        "no proto projection registered for this message pair; "
175	        "add it to proto_projection.{hpp,cpp} and to this dispatch chain");
176	    }
177	  }
178	
179	  std::string rosidl_topic_;
180	  std::string proto_topic_;
181	  bool enabled_{false};
