/// 双发器：持有 proto 发布器，提供从 rosidl 消息投影并发布的单一入口。
///
/// 模板参数：
///   RosidlMsgT  源消息（rosidl 类型）
///   ProtoT      目标消息，必须已在 register_all_types.hpp 注册过
///   Lifecycle   true 表示宿主是 lifecycle 节点，proto 侧用 LifecyclePublisher
///               并需要显式 Activate()/Deactivate()；false 时构造即可发布。
template<typename RosidlMsgT, typename ProtoT, bool Lifecycle = false>
class ProtoDualPublisher
{
public:
  /// 宿主节点类型：lifecycle 变体必须传 LifecycleNode 才能建 lifecycle 发布器。
  using NodeT = std::conditional_t<
    Lifecycle, rclcpp_lifecycle::LifecycleNode, rclcpp::Node>;
  using PublisherT = std::conditional_t<
    Lifecycle,
    rclcpp_lifecycle::LifecyclePublisher<ProtoT>,
    rclcpp::Publisher<ProtoT>>;

  /// 构造即创建发布器。
  ///
  /// \param node        宿主节点（用于 create_publisher 与日志）
  /// \param rosidl_name 已解析的 rosidl 话题名（proto 名由它派生）
  /// \param qos_depth   QoS 深度。两侧必须一致：若 proto 侧深度更小，
  ///                    突发时会先丢 proto 帧，一致性检查器会报「proto 缺帧」
  ///                    而不是「消息不一致」，掩盖真正的问题。
  /// \param enabled     总开关。false 时完全不创建发布器，
  ///                    因此也不会在 DDS 里留下一个空话题。
  ProtoDualPublisher(
    NodeT * node, const std::string & rosidl_name, std::size_t qos_depth, bool enabled)
  : rosidl_topic_(rosidl_name),
    proto_topic_(ProtoTopicName(rosidl_name)),
    enabled_(enabled)
  {
    if (!enabled_) {
      return;
    }
    // lifecycle 发布器构造后处于未激活态，必须等节点的 on_activate 调 Activate()。
    // 非 lifecycle 发布器没有激活态，构造即可发。
    pub_ = node->template create_publisher<ProtoT>(proto_topic_, rclcpp::QoS(qos_depth));
  }

